; a = U/16 in [0,1) -> a = 2^-U (U = k + f; cubic for 0.5*2^-f, then >> k).
; Uses b? no: a, x0, x1, y1.
rz_exp2:
        move    a1,x0
        move    x0,a
        asr     #19,a,a             ; k = integer part
        move    a1,x1
        move    x0,a
        and     #>$07ffff,a
        asl     #4,a,a              ; f in [0,1)
        move    a1,y1
        move    #>$fd78a6,x0
        mpy     x0,y1,a
        add     #>$0ec230,a
        move    a,x0
        mpy     x0,y1,a
        add     #>$d3c549,a
        move    a,x0
        mpy     x0,y1,a
        add     #>$3ffe5d,a         ; 0.5*2^-f
        asl     #1,a,a              ; 2^-f, up to 1.0
        asr     x1,a,a              ; >> k
        rts

